package main

import (
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

const (
	cmdCheck  = "check"
	cmdTotal  = "hours"
	cmdWeeks  = "weeks"
	cmdPay    = "gross"
	hasWeeks  = false
	hasPay    = false
	hasAuto   = true
	hasDaily  = false
	tfmt      = "dec"
	roundTo   = 5
	rmode     = "up"
	autoAfter = 300
	autoMin   = 30
	maxShift  = 840
	wstart    = 0
	thresh    = 40
	multNum   = 2
	multDen   = 1
	dailyMin  = 540
	nmax      = 12
)

var mdays = []int{31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}

type row struct {
	name string
	day  int
	mins int
}

func isDig(c byte) bool { return c >= '0' && c <= '9' }

func allDig(s string) bool {
	for i := 0; i < len(s); i++ {
		if !isDig(s[i]) {
			return false
		}
	}
	return true
}

func leap(y int) bool { return y%4 == 0 && (y%100 != 0 || y%400 == 0) }

func monthLen(y, m int) int {
	if m == 2 && leap(y) {
		return 29
	}
	return mdays[m-1]
}

func daysFromCivil(y, m, d int) int {
	n := 0
	for yy := 2000; yy < y; yy++ {
		if leap(yy) {
			n += 366
		} else {
			n += 365
		}
	}
	for mm := 1; mm < m; mm++ {
		n += monthLen(y, mm)
	}
	return n + d - 1
}

func civilFromDays(n int) (int, int, int) {
	y := 2000
	for {
		yl := 365
		if leap(y) {
			yl = 366
		}
		if n < yl {
			break
		}
		n -= yl
		y++
	}
	m := 1
	for n >= monthLen(y, m) {
		n -= monthLen(y, m)
		m++
	}
	return y, m, n + 1
}

func parseDate(s string) (int, bool) {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' || !allDig(s[:4]) || !allDig(s[5:7]) || !allDig(s[8:]) {
		return 0, false
	}
	y, _ := strconv.Atoi(s[:4])
	m, _ := strconv.Atoi(s[5:7])
	d, _ := strconv.Atoi(s[8:])
	if y < 2000 || y > 2099 || m < 1 || m > 12 || d < 1 || d > monthLen(y, m) {
		return 0, false
	}
	return daysFromCivil(y, m, d), true
}

func parseTime(s string) (int, bool) {
	if len(s) != 5 || s[2] != ':' || !allDig(s[:2]) || !allDig(s[3:]) {
		return 0, false
	}
	h, _ := strconv.Atoi(s[:2])
	m, _ := strconv.Atoi(s[3:])
	if h > 23 || m > 59 {
		return 0, false
	}
	return h*60 + m, true
}

func goodName(s string) bool {
	if len(s) < 1 || len(s) > nmax || !(s[0] >= 'a' && s[0] <= 'z') {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') && !isDig(c) && c != '_' {
			return false
		}
	}
	return true
}

func rnd(n int) int {
	if roundTo <= 1 {
		return n
	}
	switch rmode {
	case "nearest":
		return (2*n + roundTo) / (2 * roundTo) * roundTo
	case "up":
		return (n + roundTo - 1) / roundTo * roundTo
	}
	return n / roundTo * roundTo
}

func parseLine(line string) (row, string) {
	f := strings.Split(line, " ")
	if len(f) != 4 && len(f) != 5 {
		return row{}, "fields"
	}
	if !goodName(f[0]) {
		return row{}, "name"
	}
	day, ok := parseDate(f[1])
	if !ok {
		return row{}, "date"
	}
	a, ok1 := parseTime(f[2])
	b, ok2 := parseTime(f[3])
	if !ok1 || !ok2 {
		return row{}, "time"
	}
	brk := -1
	if len(f) == 5 {
		s := f[4]
		if !(len(s) >= 1 && len(s) <= 3 && allDig(s) && (len(s) == 1 || s[0] != '0')) {
			return row{}, "break"
		}
		brk, _ = strconv.Atoi(s)
		if brk > 180 {
			return row{}, "break"
		}
	}
	if a == b {
		return row{}, "times"
	}
	gross := b - a
	if b < a {
		gross = b + 1440 - a
	}
	if gross > maxShift {
		return row{}, "long"
	}
	if brk >= 0 && brk >= gross {
		return row{}, "breaklen"
	}
	ded := 0
	if brk >= 0 {
		ded = brk
	} else if hasAuto && gross > autoAfter {
		ded = autoMin
	}
	return row{f[0], day, rnd(gross - ded)}, ""
}

func fmtT(n int) string {
	if tfmt == "hm" {
		return fmt.Sprintf("%d:%02d", n/60, n%60)
	}
	h := (n*200 + 60) / 120
	return fmt.Sprintf("%d.%02d", h/100, h%100)
}

func money(c int) string { return fmt.Sprintf("%d.%02d", c/100, c%100) }

func weekStart(day int) int {
	wd := (day + 5) % 7
	return day - ((wd-wstart)%7+7)%7
}

func dateText(day int) string {
	y, m, d := civilFromDays(day)
	return fmt.Sprintf("%04d-%02d-%02d", y, m, d)
}

type wkey struct {
	name string
	ws   int
}

func split(rows []row, hol map[int]bool) map[wkey][2]int {
	type dk struct {
		name string
		day  int
	}
	days := map[dk]int{}
	for _, r := range rows {
		days[dk{r.name, r.day}] += r.mins
	}
	weeks := map[wkey]*[3]int{}
	for k, tot := range days {
		wk := wkey{k.name, weekStart(k.day)}
		w := weeks[wk]
		if w == nil {
			w = &[3]int{}
			weeks[wk] = w
		}
		if hol[k.day] {
			w[2] += tot
		} else {
			reg := tot
			if hasDaily && dailyMin < tot {
				reg = dailyMin
			}
			w[0] += reg
			w[1] += tot - reg
		}
	}
	out := map[wkey][2]int{}
	for k, w := range weeks {
		reg := w[0]
		if thresh*60 < reg {
			reg = thresh * 60
		}
		out[k] = [2]int{reg, w[1] + (w[0] - reg) + w[2]}
	}
	return out
}

func sortedKeys(m map[wkey][2]int) []wkey {
	ks := make([]wkey, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Slice(ks, func(a, b int) bool {
		if ks[a].name != ks[b].name {
			return ks[a].name < ks[b].name
		}
		return ks[a].ws < ks[b].ws
	})
	return ks
}

func usage() int {
	fmt.Fprintln(os.Stderr, "usage: timecard COMMAND [OPTIONS]")
	return 2
}

func run(args []string) int {
	if len(args) == 0 {
		return usage()
	}
	cmd := args[0]
	rates := map[string]int{}
	hol := map[int]bool{}
	if cmd == cmdCheck || cmd == cmdTotal || (hasWeeks && cmd == cmdWeeks) {
		if len(args) != 1 {
			return usage()
		}
	} else if hasPay && cmd == cmdPay {
		for i := 1; i < len(args); i += 2 {
			if i+1 >= len(args) {
				return usage()
			}
			opt, val := args[i], args[i+1]
			if opt == "--rate" {
				eq := strings.IndexByte(val, '=')
				if eq < 0 {
					return usage()
				}
				nm, cents := val[:eq], val[eq+1:]
				if _, dup := rates[nm]; !goodName(nm) || dup {
					return usage()
				}
				if !(len(cents) >= 1 && len(cents) <= 6 && allDig(cents) && cents[0] != '0') {
					return usage()
				}
				rates[nm], _ = strconv.Atoi(cents)
			} else if opt == "--holiday" {
				d, ok := parseDate(val)
				if !ok {
					return usage()
				}
				hol[d] = true
			} else {
				return usage()
			}
		}
	} else {
		return usage()
	}
	data, _ := io.ReadAll(os.Stdin)
	lines := strings.Split(string(data), "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	var rows []row
	for n, line := range lines {
		r, why := parseLine(line)
		if why != "" {
			fmt.Printf("error: line %d: %s\n", n+1, why)
			return 1
		}
		rows = append(rows, r)
	}
	switch cmd {
	case cmdCheck:
		fmt.Printf("ok %d shifts\n", len(rows))
		return 0
	case cmdTotal:
		tot := map[string]int{}
		for _, r := range rows {
			tot[r.name] += r.mins
		}
		names := make([]string, 0, len(tot))
		for n := range tot {
			names = append(names, n)
		}
		sort.Strings(names)
		for _, n := range names {
			fmt.Printf("%s %s\n", n, fmtT(tot[n]))
		}
		return 0
	}
	ws := split(rows, hol)
	keys := sortedKeys(ws)
	if hasWeeks && cmd == cmdWeeks {
		for _, k := range keys {
			v := ws[k]
			fmt.Printf("%s %s %s %s\n", k.name, dateText(k.ws), fmtT(v[0]), fmtT(v[1]))
		}
		return 0
	}
	var names []string
	seen := map[string]bool{}
	for _, k := range keys {
		if !seen[k.name] {
			seen[k.name] = true
			names = append(names, k.name)
		}
	}
	for _, n := range names {
		if _, ok := rates[n]; !ok {
			fmt.Printf("error: rate %s\n", n)
			return 1
		}
	}
	total := 0
	for _, n := range names {
		cents := 0
		for _, k := range keys {
			if k.name == n {
				v := ws[k]
				numer := (v[0]*multDen + v[1]*multNum) * rates[n]
				denom := 60 * multDen
				cents += (2*numer + denom) / (2 * denom)
			}
		}
		total += cents
		fmt.Printf("%s %s\n", n, money(cents))
	}
	if len(names) > 0 {
		fmt.Printf("TOTAL %s\n", money(total))
	}
	return 0
}

func main() {
	os.Exit(run(os.Args[1:]))
}

